/* jc_hp_watchunits.c - the `watch units` subcommand body (M1153, batch H9a,
 * UC3 part 1): the gate watcher's systemd unit files, generated not
 * hand-written (the `push units` idiom, M1147 B4; one owner per file, so this
 * file carries its own self-path / refuse / say helpers, file-local).
 *
 * Prints `jhp-gate-watch.service` and `jhp-gate-watch.timer` with THIS
 * drive's names (the jhp- prefix, this drive's config), a GENERATED marker
 * (do not edit by hand -- regenerate), and a service `ExecStart` that names
 * the WATCH COMMAND (`<argv0> watch gate --config <cfg>` -- the harness's own
 * path, readlink /proc/self/exe), not a script path. The transient unit the
 * watcher STARTS (`jhp-gate-<sha8>`) is not a generated file: the reference
 * `systemd-run`s it per commit, and the port does the same (behaviour 13).
 *
 * The timer's OnCalendar is the CONFIGURED value (host.gateOnCalendar,
 * SV:1639's idiom): the schedule comes from the config so two drives'
 * watchers never share a minute on the same host; a host block that names no
 * gateOnCalendar refuses exit 2 naming it (NO fallback -- a default schedule
 * may collide with another drive's watcher on the same host). AccuracySec=30s
 * and Persistent=true are the reference's (jhd-gate-watch.timer): a tick
 * missed while the machine was off runs at the next boot.
 *
 * Default: print both units to stdout. `-o <dir>` (the dispatch's
 * watch_out_dir): write the two files under the dir (exactly those two) and
 * print one confirmation line. A config with no usable host block refuses
 * exit 2 naming `no host block` (the push idiom). */

#include "jc_harness_config.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <unistd.h>   /* readlink */

#include "jc_platform.h"  /* jc_status, jc_write_file */
#include "jc_snprintf.h"  /* jc_snprintf, never sprintf */
#include "jc_mem.h"       /* struct jc_arena */

/* Paths hang off the config path; give the joins room, the same bound
 * jc_hp_units.c's PATH_CAP uses for the mirror joins. */
#define PATH_CAP 4352
/* A generated unit file never exceeds this (the reference's are ~1 KB; the
 * harness path / config path add at most PATH_CAP each). */
#define UNITS_TEXT_CAP 16384

/* The `watch` verb's refusal helper (the push idiom, file-local twin): the
 * units command is host-side by construction, so a config with no usable
 * `host` block is a USAGE refusal (exit 2) naming `no host block`. */
static int
watchunits_refuse_host(const struct jc_harness_config *cfg)
{
    if (cfg->host_dir_present == 0 ||
        cfg->host_dir == NULL || cfg->host_dir[0] == '\0') {
        fprintf(stderr, "jichi-harness: watch units: no host block in the "
                "config -- the watcher's units are host-side by construction; "
                "a config that names no host dir must not guess one (the "
                "host object: pushHome, gateHome, gateOnCalendar)\n");
        return 2;
    }
    return 0;
}

static void
watchunits_refuse_line(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "jichi-harness: watch units: ");
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
    fflush(stderr);
}

static void
watchunits_say_line(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fputs("watch units: ", stdout);
    vfprintf(stdout, fmt, ap);
    fputc('\n', stdout);
    va_end(ap);
    fflush(stdout);
}

/* The harness's own executable path for the unit's ExecStart (readlink
 * /proc/self/exe, the M1053 idiom; this file carries its own copy, one
 * owner per file). Returns 1 on success. */
static int
watchunits_self_path(char *out, size_t cap)
{
    char buf[PATH_CAP];
    ssize_t n;
    n = readlink("/proc/self/exe", buf, sizeof buf - 1);
    if (n <= 0 || n >= (ssize_t)sizeof buf) {
        return 0;
    }
    buf[n] = '\0';
    if (jc_snprintf(out, cap, "%s", buf) >= (int)cap) {
        return 0;
    }
    return 1;
}

/* Build the jhp-gate-watch.service text into `dst` (the reference's shape
 * with THIS drive's names: the jhp- prefix, a GENERATED marker, and an
 * ExecStart that names the WATCH COMMAND -- `<harness> watch gate --config
 * <cfg>` -- not a script path). Returns 1 on success, 0 when the buffer is
 * too small. */
static int
build_watch_service(const char *harness, const char *cfg_path,
                    char *dst, size_t cap)
{
    static const char c1a[] =
        "# jhp-gate-watch.service -- GENERATED by `jichi-harness watch "
        "units` (M1153, batch H9a, 2026-11-09); NOT hand-written: do not "
        "edit by hand -- regenerate it.\n";
    static const char c1b[] =
        "# The harness port drive's gate watcher (the user-level oneshot). "
        "Runs `<harness> watch gate --config <config>`: ONE tick of the "
        "gate watcher -- the last READY line in the drive's LOG is gated by "
        "the machine's own clock, not by a session that happens to be awake "
        "(the 2026-11-04 16.5-hour gap's lesson).\n";
    static const char c1c[] =
        "# Started by jhp-gate-watch.timer; the tick's say lines are its "
        "stdout, the oneshot's journal.\n";
    static const char body_a[] =
        "[Unit]\n"
        "Description=jichi harness port drive: gate watcher tick (watch "
        "gate)\n"
        "After=network-online.target\n"
        "\n"
        "[Service]\n"
        "Type=oneshot\n"
        "Nice=10\n";
    static const char exec_fmt[] =
        "ExecStart=%s watch gate --config %s\n";
    size_t off;

    off = strlen(c1a) + strlen(c1b) + strlen(c1c) + strlen(body_a);
    if (off + 1 + strlen(harness) + 1 + strlen(cfg_path) + 2 >= cap) {
        return 0;
    }
    memcpy(dst, c1a, strlen(c1a));
    memcpy(dst + strlen(c1a), c1b, strlen(c1b));
    memcpy(dst + strlen(c1a) + strlen(c1b), c1c, strlen(c1c));
    memcpy(dst + strlen(c1a) + strlen(c1b) + strlen(c1c), body_a,
           strlen(body_a));
    if (jc_snprintf(dst + off, cap - off, exec_fmt, harness, cfg_path) < 0) {
        return 0;
    }
    return 1;
}

/* Build the jhp-gate-watch.timer text into `dst` (the reference's shape with
 * THIS drive's names: the jhp- prefix; the AccuracySec / Persistent /
 * WantedBy values IDENTICAL to the reference's jhd-gate-watch.timer). The
 * OnCalendar is the CONFIGURED value (host.gateOnCalendar, SV:1639): the
 * schedule comes from the config so two drives' watchers never share a
 * minute on the same host -- no fixed offset holds (each drive's tick
 * minute moves with its own run), so a constant schedule here is the defect
 * the config read fixes. Returns 1 on success, 0 when the buffer is too
 * small. */
static int
build_watch_timer(const char *oncalendar, char *dst, size_t cap)
{
    static const char head[] =
        "# jhp-gate-watch.timer -- GENERATED by `jichi-harness watch units` "
        "(M1153, batch H9a, 2026-11-09); NOT hand-written: do not edit by "
        "hand -- regenerate it.\n"
        "# The schedule comes from the config (host.gateOnCalendar) so two "
        "drives' watchers never share a minute on the same host. "
        "Persistent: a tick missed while the machine was off runs at the "
        "next boot.\n"
        "[Unit]\n"
        "Description=jichi harness port drive: gate watcher (scheduled)\n"
        "\n"
        "[Timer]\n";
    static const char oncal_fmt[] =
        "OnCalendar=%s\n";
    static const char tail[] =
        "AccuracySec=30s\n"
        "Persistent=true\n"
        "\n"
        "[Install]\n"
        "WantedBy=timers.target\n";
    size_t off;
    if (oncalendar == NULL || oncalendar[0] == '\0') {
        return 0;
    }
    if (strlen(head) + strlen(oncal_fmt) + strlen(oncalendar) + 1 +
        strlen(tail) + 1 >= cap) {
        return 0;
    }
    memcpy(dst, head, strlen(head));
    off = strlen(head);
    off += (size_t)jc_snprintf(dst + off, cap - off, oncal_fmt, oncalendar);
    memcpy(dst + off, tail, strlen(tail));
    dst[off + strlen(tail)] = '\0';
    return 1;
}

/* `watch units`: the systemd unit files, generated not hand-written. The
 * dispatch passes the `-o <dir>` value (NULL when absent). Default: print
 * both generated units to stdout. With `-o`: write the two files under the
 * dir (creating nothing but the files) and print a confirmation line. */
int
jc_hp_watchunits_run(const char *config_path, const char *out_dir,
                     struct jc_arena *a)
{
    struct jc_harness_config cfg;
    char harness[PATH_CAP];
    char svc[UNITS_TEXT_CAP];
    char tmr[UNITS_TEXT_CAP];
    char svcpath[PATH_CAP + 32];
    char tmrpath[PATH_CAP + 32];
    jc_status st;
    int rc;

    (void)a;   /* the config load uses a for its arena strings */
    if (config_path == NULL) {
        watchunits_refuse_line("needs --config <file> (the harness "
                                "configuration)");
        return 2;
    }
    st = jc_harness_config_load(config_path, &cfg, a);
    if (st != JC_OK) {
        const char *msg = jc_harness_config_error(&cfg);
        watchunits_refuse_line("%s",
            (msg != NULL) ? msg : "could not read the harness config");
        return 2;
    }
    rc = watchunits_refuse_host(&cfg);
    if (rc != 0) {
        return rc;
    }
    if (cfg.host_gate_oncalendar == NULL ||
        cfg.host_gate_oncalendar[0] == '\0') {
        watchunits_refuse_line("the host block names no gateOnCalendar -- "
            "the generated jhp-gate-watch.timer's schedule comes from the "
            "config (host.gateOnCalendar) so two drives' watchers never "
            "share a minute on the same host; refused (no fallback to a "
            "default schedule)");
        return 2;
    }
    if (!watchunits_self_path(harness, sizeof harness)) {
        watchunits_refuse_line("could not resolve the harness's own path "
            "(readlink /proc/self/exe failed); the unit's ExecStart cannot "
            "name the watch command; refused");
        return 1;
    }
    if (!build_watch_service(harness, config_path, svc, sizeof svc)) {
        watchunits_refuse_line("could not build the jhp-gate-watch.service "
            "text (the paths are too long); refused");
        return 1;
    }
    if (!build_watch_timer(cfg.host_gate_oncalendar, tmr, sizeof tmr)) {
        watchunits_refuse_line("could not build the jhp-gate-watch.timer "
            "text; refused");
        return 1;
    }
    if (out_dir == NULL || out_dir[0] == '\0') {
        /* Default: both units to stdout, service first, timer second,
         * separated by a blank line. */
        fputs(svc, stdout);
        fputc('\n', stdout);
        fputs(tmr, stdout);
        fflush(stdout);
        return 0;
    }
    /* -o <dir>: write the two files (exactly those two, nothing else) and
     * print one confirmation line. */
    if (jc_snprintf(svcpath, sizeof svcpath, "%s/jhp-gate-watch.service",
                    out_dir) >= (int)sizeof svcpath ||
        jc_snprintf(tmrpath, sizeof tmrpath, "%s/jhp-gate-watch.timer",
                    out_dir) >= (int)sizeof tmrpath) {
        watchunits_refuse_line("the -o directory path is too long to build "
            "the unit file paths; refused");
        return 2;
    }
    if (jc_write_file(svcpath, svc, (jc_size)strlen(svc)) != JC_OK) {
        watchunits_refuse_line("could not write %s (the -o directory is not "
            "writable?); refused", svcpath);
        return 1;
    }
    if (jc_write_file(tmrpath, tmr, (jc_size)strlen(tmr)) != JC_OK) {
        watchunits_refuse_line("could not write %s (the -o directory is not "
            "writable?); refused", tmrpath);
        return 1;
    }
    watchunits_say_line("wrote the two generated units: %s and %s",
                        svcpath, tmrpath);
    return 0;
}
